/// An object of InteractionConstraint, with every inherited stored property as a field.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct InteractionConstraintObj {
    pub owned_comment: Vec<Value>,
    pub owning_template_parameter: Option<Obj>,
    pub template_parameter: Option<Obj>,
    pub name: Option<Arc<str>>,
    pub name_expression: Option<Obj>,
    pub visibility: u32,
    pub constrained_element: Vec<Value>,
    pub context: Option<Obj>,
    pub specification: Option<Obj>,
    pub maxint: Option<Obj>,
    pub minint: Option<Obj>,
}

impl Reflect for InteractionConstraintObj {
    fn class(&self) -> ClassId {
        INTERACTION_CONSTRAINT
    }
    fn get(&self, prop: PropId) -> Option<Value> {
        match prop {
            parameterable_element::OWNING_TEMPLATE_PARAMETER => Some(self.owning_template_parameter.map_or(Value::Null, Value::Ref)),
            parameterable_element::TEMPLATE_PARAMETER => Some(self.template_parameter.map_or(Value::Null, Value::Ref)),
            named_element::NAME => Some(self.name.clone().map_or(Value::Null, Value::Str)),
            named_element::NAME_EXPRESSION => Some(self.name_expression.map_or(Value::Null, Value::Ref)),
            packageable_element::VISIBILITY => Some(Value::Enum(self.visibility)),
            constraint::CONTEXT => Some(self.context.map_or(Value::Null, Value::Ref)),
            constraint::SPECIFICATION => Some(self.specification.map_or(Value::Null, Value::Ref)),
            interaction_constraint::MAXINT => Some(self.maxint.map_or(Value::Null, Value::Ref)),
            interaction_constraint::MININT => Some(self.minint.map_or(Value::Null, Value::Ref)),
            _ => None,
        }
    }
    fn set(&mut self, prop: PropId, value: Value) -> Result<(), String> {
        match prop {
            parameterable_element::OWNING_TEMPLATE_PARAMETER => {
                match value {
                    Value::Null => self.owning_template_parameter = None,
                    Value::Ref(v) => self.owning_template_parameter = Some(v),
                    other => return Err(format!("not a reference: {other}")),
                }
                Ok(())
            }
            parameterable_element::TEMPLATE_PARAMETER => {
                match value {
                    Value::Null => self.template_parameter = None,
                    Value::Ref(v) => self.template_parameter = Some(v),
                    other => return Err(format!("not a reference: {other}")),
                }
                Ok(())
            }
            named_element::NAME => {
                match value {
                    Value::Null => self.name = None,
                    Value::Str(v) => self.name = Some(v),
                    other => return Err(format!("not a string: {other}")),
                }
                Ok(())
            }
            named_element::NAME_EXPRESSION => {
                match value {
                    Value::Null => self.name_expression = None,
                    Value::Ref(v) => self.name_expression = Some(v),
                    other => return Err(format!("not a reference: {other}")),
                }
                Ok(())
            }
            packageable_element::VISIBILITY => {
                match value {
                    Value::Enum(v) => self.visibility = v,
                    other => return Err(format!("not a literal: {other}")),
                }
                Ok(())
            }
            constraint::CONTEXT => {
                match value {
                    Value::Null => self.context = None,
                    Value::Ref(v) => self.context = Some(v),
                    other => return Err(format!("not a reference: {other}")),
                }
                Ok(())
            }
            constraint::SPECIFICATION => {
                match value {
                    Value::Null => self.specification = None,
                    Value::Ref(v) => self.specification = Some(v),
                    other => return Err(format!("not a reference: {other}")),
                }
                Ok(())
            }
            interaction_constraint::MAXINT => {
                match value {
                    Value::Null => self.maxint = None,
                    Value::Ref(v) => self.maxint = Some(v),
                    other => return Err(format!("not a reference: {other}")),
                }
                Ok(())
            }
            interaction_constraint::MININT => {
                match value {
                    Value::Null => self.minint = None,
                    Value::Ref(v) => self.minint = Some(v),
                    other => return Err(format!("not a reference: {other}")),
                }
                Ok(())
            }
            _ => Err(format!("no single-valued property {} on InteractionConstraint", prop.0)),
        }
    }
    fn list(&self, prop: PropId) -> Option<&[Value]> {
        match prop {
            element::OWNED_COMMENT => Some(&self.owned_comment),
            constraint::CONSTRAINED_ELEMENT => Some(&self.constrained_element),
            _ => None,
        }
    }
    fn list_mut(&mut self, prop: PropId) -> Option<&mut Vec<Value>> {
        match prop {
            element::OWNED_COMMENT => Some(&mut self.owned_comment),
            constraint::CONSTRAINED_ELEMENT => Some(&mut self.constrained_element),
            _ => None,
        }
    }
}

